/** The Larch Yards Junction Plaza's rack — the plaza's east edge, 4 m
 *  west of the shipped bench pair (x 149.2/154.8, z 12.5). */
const PLAZA_RACK: Array<{ id: string; x: number; z: number; rotY: number }> = [
  { id: 'bike-rack-a1e7c3', x: 143.5, z: 12.5, rotY: 0 },
];

export interface PolyforkStreetKitResult {
  /** The solids World must own (World converts with boxFromCenter). */
  colliders: PolyforkCollider[];
}

/** Builds the street kit's three baked batches. Call BEFORE bakeStatics
 *  (the everything-static-before-the-bake law). */
export function buildPolyforkStreetKit(
  scene: THREE.Scene, vc: (fog: boolean) => THREE.MeshLambertMaterial,
): PolyforkStreetKitResult {
  const colliders: PolyforkCollider[] = [];
  if (!polyforkOn) return { colliders };

  const batch = (name: string, items: typeof NORTH_KIT): void => {
    const acc = new PolyforkAcc();
    for (const it of items) {
      acc.place(it.id, it.x, it.z, it.rotY, it.y ?? 0);
      if (it.solid) colliders.push(it.solid);
    }
    emitPolyfork(scene, vc(true), name, acc.toGeometry(), true, true);
  };
  batch('Polyfork_Alder_Kit_N', NORTH_KIT);
  batch('Polyfork_Alder_Kit_S', SOUTH_KIT);
  batch('Polyfork_Plaza_Rack', PLAZA_RACK);
  return { colliders };
}

// ------------------------------------------------- 2. Catalpa dock fleet ----

/** The dock fleet's placements — vehicles BACKED INTO the dock faces the
 *  W-C1 district built with none (the kit's trucks face +z; rear at -z):
 *    - CJN-02 (Corbin & Sons, z 20) and CJN-04 (Starlawn, z -24): west
 *      rows' doors face EAST at x -422 → rear at -421.7, nose +x.
 *    - CJN-08 (United Cotton Duck, z 8): east row's door faces WEST at
 *      x -400 → rear at -400.4, nose -x.
 *    - the garbage truck rides the spur's south-east edge (clear of the
 *      bollard stations z -46/-26/... and of the footbridge at z -34).
 *    - the food truck parks at the headhouse's walk (z 30, clear of the
 *      z 14/34 bollards and of the station slab z 10.4..15.4).
 *  Every spot sits between the bollard stations (z -46/-26/-6/14/34/54). */
const CATALPA_FLEET: Array<{ id: string; x: number; z: number; rotY: number; solid: PolyforkCollider }> = [
  { id: 'delivery-truck-a9537e', x: -418.7, z: 20, rotY: Math.PI / 2,
    solid: { x: -418.7, y: 1.35, z: 20, w: 6.0, h: 2.7, d: 2.62 } },
  { id: 'delivery-truck-a9537e', x: -418.7, z: -24, rotY: Math.PI / 2,
    solid: { x: -418.7, y: 1.35, z: -24, w: 6.0, h: 2.7, d: 2.62 } },
  { id: 'delivery-truck-a9537e', x: -403.4, z: 8, rotY: -Math.PI / 2,
    solid: { x: -403.4, y: 1.35, z: 8, w: 6.0, h: 2.7, d: 2.62 } },
  { id: 'garbage-truck-a7ffbf', x: -401.8, z: -51, rotY: 0,
    solid: { x: -401.8, y: 1.75, z: -51, w: 2.88, h: 3.49, d: 8.0 } },
  { id: 'food-truck-3c4e0e', x: -402.4, z: 30, rotY: 0,
    solid: { x: -402.4, y: 1.64, z: 30, w: 3.76, h: 3.28, d: 6.53 } },
];

/** Builds the fleet as ONE vertex-colored mesh inside the CJN zone group
 *  (+0 standing at spawn — the group is dark until catalpaSurface).
 *  Returns the fleet's solids for the district's collider list. */
export function buildCatalpaDockFleet(
  group: THREE.Group, material: THREE.MeshLambertMaterial,
): PolyforkCollider[] {
  if (!polyforkOn) return [];
  const acc = new PolyforkAcc();
  const colliders: PolyforkCollider[] = [];
  for (const v of CATALPA_FLEET) {
    acc.place(v.id, v.x, v.z, v.rotY);
    colliders.push(v.solid);
  }
  const m = emitPolyfork(group, material, 'CJN_Polyfork_Fleet', acc.toGeometry(), true, true);
  m.name = 'CJN_Polyfork_Fleet';
  return colliders;
}

// --------------------------------------------------- 3. the Larch trucks ----

/** One parked delivery truck into the Larch docks' accumulator — the
 *  trucks() swap's body. The kit truck faces +z (rear -z); `along`
 *  mirrors the shipped park table's axis (nose +lx). */
export function placePolyforkTruck(acc: PolyforkAcc, x: number, z: number, along: 'x' | 'z'): void {
  acc.place('delivery-truck-a9537e', x, z, along === 'x' ? Math.PI / 2 : 0);
}
